import java.util.Scanner;

public class Main {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        int 甲要记 = sc.nextInt();
        int 乙要记 = sc.nextInt();

        Cat 甲 = new Cat(甲要记);
        Cat 乙 = new Cat(乙要记);

        甲.start();
        乙.start();

        甲.join();
        乙.join();

        System.out.println("账本：" + Cat.账本 + " {unit}");
    }
}

class Cat extends Thread {
    static final Object 账本锁 = new Object();
    static int 账本 = 0;

    int 要记;

    Cat(int 要记) {
        this.要记 = 要记;
    }

    public void run() {
        for (int i = 0; i < 要记; i++) {
            synchronized (账本锁) {
                账本 = 账本 + 1;
            }
        }
    }
}
